// ==========================================================
// Monta o payload da Meta Conversions API (evento Lead)
// Faz o hash SHA-256 dos dados pessoais (exigido pela Meta)
// ==========================================================
const crypto = require('crypto');

// Hash SHA-256 para texto (email, nome, sobrenome): trim + lowercase
function hash(value) {
  if (value === undefined || value === null || value === '') return undefined;
  const normalized = String(value).trim().toLowerCase();
  if (!normalized) return undefined;
  return crypto.createHash('sha256').update(normalized).digest('hex');
}

// Hash SHA-256 para telefone: mantem somente digitos (com DDI), sem +
function hashPhone(value) {
  if (value === undefined || value === null || value === '') return undefined;
  const digits = String(value).replace(/\D/g, '');
  if (!digits) return undefined;
  return crypto.createHash('sha256').update(digits).digest('hex');
}

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Dados vindos da LP ---
const email = body.email;
const phone = body.numero;
const firstName = body.nome;
const lastName = body.sobrenome;

// --- Dados de contexto (melhoram a qualidade do match, NAO tem hash) ---
const ip = (headers['x-forwarded-for'] || '').split(',')[0].trim() || undefined;
const userAgent = headers['user-agent'] || undefined;
const sourceUrl = headers['referer'] || headers['origin'] || undefined;

// --- user_data ---
const userData = {};
if (hash(email)) userData.em = [hash(email)];
if (hashPhone(phone)) userData.ph = [hashPhone(phone)];
if (hash(firstName)) userData.fn = [hash(firstName)];
if (hash(lastName)) userData.ln = [hash(lastName)];
if (ip) userData.client_ip_address = ip;
if (userAgent) userData.client_user_agent = userAgent;

// event_id para deduplicacao caso um dia use tambem o Pixel no navegador
const eventId = crypto.randomUUID();

const payload = {
  data: [
    {
      event_name: 'Lead',
      event_time: Math.floor(Date.now() / 1000),
      event_id: eventId,
      action_source: 'website',
      event_source_url: sourceUrl,
      user_data: userData
    }
  ]
  // Para testar no "Test Events" da Meta, descomente a linha abaixo
  // e cole o codigo que aparece na aba Test Events do Gerenciador de Eventos:
  // , test_event_code: 'TEST12345'
};

return [{ json: payload }];
